mapper.select:
SELECT id, department_id, userid, type, subject, create_time, update_time
FROM sys_department_admin
WHERE department_id = #{departmentId}
AND userid = #{userid}
LIMIT 1

mapper.update:
UPDATE sys_department_admin
SET type = #{type},
    subject = #{subject},
    update_time = #{updateTime}
WHERE department_id = #{departmentId}
AND userid = #{userid}
